import numpy as np
from patsy import dmatrix
D=np.linspace(0,1,5)
for formula in ['bs(D, df=5, degree=3)', 'bs(D, df=5, degree=3) - 1', 'bs(D, df=5, degree=3, include_intercept=False)', 'bs(D, df=5, degree=3, include_intercept=False) - 1']:
    try:
        X=dmatrix(formula, {'D':D})
        print(formula, X.shape)
        print(np.asarray(X)[:2])
    except Exception as e:
        print(formula, 'ERR', e)
